                        'Musik arak-arakan dari Kerambitan yang didominasi bunyi ketukan bambu. Alatnya antara lain kulkul bambu dan okokan, ditambah sepasang kendang cedugan, ceng-ceng kopyak, gong, kemong, dan suling. Dulu warga memainkannya secara spontan pada malam Pengerupukan untuk memohon keselamatan, karena bunyi-bunyian itu dipercaya mengusir penyebab wabah. A.A. Ngurah Oka Silagunadha dari Puri Anyar Kerambitan kemudian mengolahnya menjadi pertunjukan Tektekan Calonarang di Desa Baturiti untuk wisatawan. Tahunnya berbeda menurut sumber, antara 1967 dan 1970. Pertunjukan ini memakai barong dan rangda sakral, dan penelitian di Baturiti mencatat warga setempat mendukungnya, berbeda dari sikap kebanyakan masyarakat Bali terhadap unsur sakral. Tektekan juga mengiringi fragmentari Puputan Margarana.',
