                    deskripsi:
                        'Kain tenun ikat ganda (dobel ikat) dari Tenganan Pegringsingan. Di Indonesia teknik ini hanya dikerjakan di desa ini. Benang lungsi dan pakan sama-sama diikat dan dicelup sebelum ditenun, dan motif baru utuh ketika keduanya bertemu tepat di alat tenun. Warnanya terbatas pada warna alam: krem, merah tua, dan biru kehitaman. Satu kain memakan waktu dua sampai lima tahun, sedangkan tahap menenunnya sendiri sekitar sebulan. Ada sekitar 20 jenis, dengan motif seperti lubeng, cemplong, wayang, dan sanan empeg. Gringsing sering diartikan tidak sakit, dan warga percaya Dewa Indra mengajarkan keahlian ini kepada perempuan Tenganan. Selama benang lungsinya belum dipotong, kain hanya dipakai untuk upacara dewa dan leluhur.',
