                        'Gamelan sakral berbilah besi yang termasuk tua di Bali. Di Tenganan bilahnya disebut Bhatara Bagus Selonding dan dipandang sebagai piturun, benda yang tidak dibuat tangan manusia. Menurut mitos, suara selonding turun bergelombang, mula-mula ke Bungaya lalu ke Tenganan. Tiga bilah pusaka di Tenganan tidak boleh ditabuh dan hanya disimpan sebagai pretima, sedangkan perangkat yang dimainkan dikembangkan dari sana. Perangkat Tenganan kini berjumlah 40 bilah pada delapan tungguh, dengan tujuh nada. Penabuhnya harus lolos seleksi dan pelatihan di bawah kelian desa sebelum diangkat menjadi juru gamel, dan sebagian gending geguron tidak diperdengarkan untuk umum. Selonding mengiringi upacara besar seperti Usaba Dangsil dan Usaba Sumbu.',
