                        'Gaya gamelan yang lahir di Bali Utara pada awal abad ke-20, dikenal dari bunyi serempak yang keras dan membangkitkan semangat. Gamelan ini dianggap perpaduan Gender Wayang, Gong Gede, dan Pelegongan. Kompetisi pertama yang tercatat digelar di Jagaraga pada Desember 1915, menurut catatan Colin McPhee, tetapi sebagian sumber menyebut Bungkulan sudah memilikinya sekitar 1914. Pan Wandres dan Pan Cening Liyana dianggap perintisnya, dan Gde Manik dari Jagaraga menjadi komponis dan guru yang berpengaruh. Dibanding Gong Gede, perangkat ini lebih ramping: gangsa memakai sembilan atau sepuluh bilah, ceng-ceng dikurangi, dan kendang ditabuh dengan tangan. Gaya Bali Utara dan Bali Selatan berbeda, dan gaya utara terdengar lebih keras.',
