                        'Tari wali yang lahir dari pertemuan budaya Bali dan Tionghoa, disakralkan warga Renon dan Semawang, Sanur. Tahun penciptaannya belum diketahui. Satu versi menyebut tari ini berawal dari gong yang dibawa leluhur Renon dari Blanjong, dan namanya konon berasal dari ucapan Ratu Tuan yang terdengar seperti logat Cina saat pentas. Ada dua kelompok. Baris selem berkemeja hitam berkerah Cina, baris putih berbaju putih, keduanya bertopi lebar, berpedang, dan tanpa sepatu. Pemimpinnya berjenggot palsu, dan pemimpin baris putih bertopi gaya Belanda. Geraknya didominasi pencak silat, diiringi gong beri, gong datar yang dalam naskah kuno disebut gamelan perang. Pementasan hanya boleh di pura tertentu, biasanya saat piodalan.',
